#include <iostream>
using namespace std;
template <typename T>              // T is a type parameter (class T also works)
T maxOf(T a, T b) { return (a > b) ? a : b; }
int main() {
    cout << maxOf(3, 7) << endl;         // T deduced as int    -> 7
    cout << maxOf(2.5, 1.5) << endl;     // T deduced as double -> 2.5
    cout << maxOf<double>(4, 6.5);       // explicit T: 4 converted to double -> 6.5
    // maxOf(3, 4.5);   error: T cannot be deduced as both int and double
}

template <typename T, typename U>
void show(T a, U b) { cout << a << " " << b << endl; }
template <typename R, typename T>
R convert(T x) { return static_cast<R>(x); }   // R is not deducible: must be given
int main() {
    show(1, "one");             // T = int, U = const char*
    show<double>(2, 3);         // T = double (explicit), U = int (deduced) -> 2 3
    cout << convert<int>(3.9);  // R = int explicit, T = double deduced -> 3
}

template <typename T> void print(T x)   { cout << "template: " << x << endl; }
void print(int x)                       { cout << "int: " << x << endl; }
template <typename T> void print(T* p)  { cout << "pointer: " << *p << endl; }
int main() {
    int n = 5;
    print(5);     // int: 5        exact non-template match wins
    print(2.5);   // template: 2.5  only the template fits without conversion
    print(&n);    // pointer: 5    more specialised template (T*) preferred
    print('a');   // template: a   char->int would need a promotion; T = char is exact
}

template <class T, int N = 10>     // type parameter T, non-type parameter N with default
class Stack {
    T data[N]; int top;
public:
    Stack() : top(-1) {}
    void push(T x);                // declared here, defined outside the class
    T pop() { return data[top--]; }
    bool empty() const { return top == -1; }
};
template <class T, int N>          // the template header is repeated for every outside definition
void Stack<T, N>::push(T x) { if (top < N - 1) data[++top] = x; }
int main() {
    Stack<int> s;  Stack<double, 5> d;   // two distinct classes are generated
    s.push(1); s.push(2); cout << s.pop();  // 2
}

#include <iostream>
