#include <vector>
#include <list>
vector<int> v = {10, 20, 30};
for (vector<int>::iterator it = v.begin(); it != v.end(); ++it)
    cout << *it << " ";                 // 10 20 30   (dereference like a pointer)
list<int> l = {1, 2, 3};
list<int>::iterator li = l.begin();
++li; --li;                             // ok: list iterators are bidirectional
// li += 2;   error: no random access on a list iterator
cout << *(v.begin() + 2);               // 30: vector iterators are random-access
for (int x : l) cout << x;              // range-for uses begin()/end() implicitly: 123

#include <vector>
#include <algorithm>
#include <numeric>
vector<int> v = {5, 1, 4, 2};
v.push_back(3);                                           // size 5, grows automatically
sort(v.begin(), v.end());                                 // 1 2 3 4 5
reverse(v.begin(), v.end());                              // 5 4 3 2 1
cout << v[0] << " " << v.size() << endl;                  // 5 5
cout << accumulate(v.begin(), v.end(), 0) << endl;        // 15
cout << (find(v.begin(), v.end(), 4) != v.end()) << endl; // 1 (found)
cout << *min_element(v.begin(), v.end()) << endl;         // 1
sort(v.begin(), v.end(), greater<int>());                 // descending: 5 4 3 2 1

#include <map>
#include <string>
map<string, int> marks;
marks["Sita"] = 80;  marks["Ram"] = 65;  marks["Hari"] = 72;
marks["Ram"] += 5;                       // existing key: value updated to 70
for (auto &p : marks)                    // keys visited in sorted order
    cout << p.first << ":" << p.second << " ";
// Hari:72 Ram:70 Sita:80
cout << marks.count("Gita") << endl;     // 0 (absent, nothing inserted)
cout << marks["Gita"] << endl;           // 0, but operator[] has now INSERTED Gita
cout << marks.size();                    // 4

#include <iostream>
#include <map>
#include <string>
using namespace std;
int main() {
    map<string, int> stock = {{"pen", 5}};
    auto r = stock.insert({"pen", 9});
    cout << r.second << " " << stock["pen"] << "\n";
    if (stock.find("ink") == stock.end()) cout << "no ink\n";
    int n = stock["ink"];
    cout << n << " " << stock.size() << "\n";
    stock["cap"] = 2;
    for (auto &p : stock) cout << p.first << "=" << p.second << " ";
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
int main() {
    vector<int> v = {4, 7, 4, 1, 4, 9};
    auto newEnd = remove(v.begin(), v.end(), 4);
    cout << v.size() << " " << (newEnd - v.begin()) << "\n";
    v.erase(newEnd, v.end());
    for (auto it = v.begin(); it != v.end(); )
        if (*it == 1) it = v.erase(it); else ++it;
    for (int x : v) cout << x << " ";
    cout << "| size " << v.size() << "\n";
}

