#include <stdexcept>
double divide(int a, int b) {
    if (b == 0) throw runtime_error("division by zero");   // throw an object
    return (double)a / b;
}
int main() {
    try {
        cout << divide(10, 2) << endl;   // 5
        cout << divide(1, 0) << endl;    // throws: nothing from this line prints
        cout << "not reached";
    } catch (const runtime_error &e) {   // catch by reference
        cout << "Error: " << e.what();   // Error: division by zero
    }
    cout << " done";                     // execution resumes after the try-catch
}

void inner() {
    try { throw 42; }                                          // int thrown
    catch (int e) { cout << "inner " << e << ", "; throw; }   // rethrow the same object
}
int main() {
    try { inner(); }
    catch (const char *s) { cout << "string"; }
    catch (int e)         { cout << "outer " << e; }   // inner 42, outer 42
    catch (...)           { cout << "anything"; }      // catch-all must be last
    try { throw 3.5; }
    catch (int)    { cout << " int"; }                 // not chosen: no double->int conversion
    catch (double) { cout << " double"; }              //  double
}

class RangeError {                    // user-defined exception class carrying data
    int value;
public:
    RangeError(int v) : value(v) {}   // the argument travels with the exception
    int get() const { return value; }
};
void setAge(int a) { if (a < 0 || a > 150) throw RangeError(a); }
int main() {
    try { setAge(200); }
    catch (const RangeError &e) { cout << "Bad age " << e.get() << endl; }  // Bad age 200
    try { throw out_of_range("index 7"); }
    catch (const exception &e) { cout << e.what(); }   // base handler catches derived: index 7
}

#include <exception>
void f() noexcept { }             // promises never to throw
void g() throw();                 // old-style specification: deprecated in C++11
void h() { throw 1; }
int main() {
    set_terminate([] { cout << "terminate called"; abort(); });
    cout << noexcept(f()) << noexcept(h()) << endl;   // 10 (compile-time check)
    h();                          // no enclosing try anywhere -> std::terminate()
    cout << "never printed";
}

#include <iostream>
using namespace std;
struct Log {
    char n;
    Log(char c) : n(c) { cout << "+" << n << " "; }
    ~Log() { cout << "-" << n << " "; }
};
void inner() { Log c('c'); throw 42; }
void middle() { Log b('b'); inner(); cout << "never "; }
int main() {
    Log a('a');
    try { middle(); }
    catch (int e) { cout << "caught " << e << " "; }
    cout << "end ";
}

#include <iostream>
#include <stdexcept>
#include <string>
using namespace std;
struct FileError : runtime_error { FileError(const string &m) : runtime_error(m) {} };
void load(int how) {
    try { throw FileError("missing"); }
    catch (runtime_error &e) { if (how == 0) throw; else throw e; }
}
int main() {
    for (int how = 0; how < 2; how++)
        try { load(how); }
        catch (FileError &e) { cout << "FileError: " << e.what() << "\n"; }
        catch (runtime_error &e) { cout << "runtime_error: " << e.what() << "\n"; }
}

